        <h2 class="channel-header-name"># @ChannelName</h2>
        <p class="channel-header-desc">@ChannelDescription</p>
    </div>

    <div class="message-list" @ref="messageListRef" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }
        @foreach (var message in Messages)
        {
            <MessageBubble Message="message"
                           ReplyCount="GetReplyCount(message.Id)"
                           OnOpenThread="OnOpenThread"
                           OnReact="OnReact"
                           OnReactWithEmoji="OnReactWithEmoji" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-input"
                  @bind="newMessageText"
                  @bind:event="oninput"
                  @onkeydown="HandleKeyDown"
                  placeholder="@($"Message #{ChannelName}")"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageText)">
            Send
        </button>
    </div>
