toolArgs.file_text:
.channel-sidebar {
    width: 100%;
    height: 100%;
    background-color: #2b2d31;
    color: #b5bac1;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
    border-bottom: 1px solid #1e1f22;
}

.channel-list {
    list-style: none;
    padding: 8px;
    margin: 0;
}

.channel-item {
    padding: 8px 12px;
    border-radius: 4px;
    cursor: pointer;
    margin-bottom: 2px;
    position: relative;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background-color: #35373c;
}

.channel-item.active {
    background-color: #404249;
    color: #f2f3f5;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: inherit;
}

.channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background-color: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

