toolArgs.file_text:
.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #313338;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.channel-header-name {
    margin: 0;
    font-size: 1.1rem;
    color: #f2f3f5;
    font-weight: 700;
}

.channel-header-desc {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.loading-indicator {
    text-align: center;
    color: #949ba4;
    font-size: 0.8rem;
    padding: 8px;
}

.message-input-area {
    padding: 12px 16px;
    border-top: 1px solid #1e1f22;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-input {
    flex: 1;
    background-color: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 14px;
    color: #dbdee1;
    font-size: 0.9rem;
    resize: none;
    min-height: 44px;
    max-height: 120px;
    font-family: inherit;
    outline: none;
}

.message-input::placeholder {
    color: #6d6f78;
}

.send-btn {
    background-color: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background-color 0.15s;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background-color: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

