.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #2b2d31;
    border-left: 1px solid #1e1f22;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.thread-title {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
    font-weight: 700;
}

.thread-close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.thread-close-btn:hover {
    background-color: #35373c;
    color: #f2f3f5;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    background-color: #232428;
    flex-shrink: 0;
}

.root-author {
    font-weight: 600;
    color: #f2f3f5;
    font-size: 0.9rem;
}

.root-content {
    margin: 6px 0 0;
    color: #dbdee1;
    font-size: 0.85rem;
    line-height: 1.4;
}

.thread-divider {
    padding: 8px 16px;
    font-size: 0.75rem;
    color: #949ba4;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.thread-reply {
    padding: 8px 16px;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.thread-reply:hover {
    background-color: #35373c;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-author {
    font-weight: 600;
    color: #f2f3f5;
    font-size: 0.85rem;
}

.reply-time {
    font-size: 0.7rem;
    color: #949ba4;
}

.reply-content {
    color: #dbdee1;
    font-size: 0.85rem;
    line-height: 1.4;
}

.thread-input-area {
    padding: 12px 16px;
    border-top: 1px solid #1e1f22;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    flex-shrink: 0;
}

.thread-input {
    flex: 1;
    background-color: #383a40;
    border: none;
    border-radius: 8px;
    padding: 8px 12px;
    color: #dbdee1;
    font-size: 0.85rem;
    resize: none;
    min-height: 36px;
    max-height: 80px;
    font-family: inherit;
    outline: none;
}

.thread-input::placeholder {
    color: #6d6f78;
}

.reply-btn {
    background-color: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 8px 16px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
    transition: background-color 0.15s;
}

.reply-btn:hover:not(:disabled) {
    background-color: #4752c4;
}

.reply-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

