+    }
+
+    private async Task HandleReact(int messageId)
+    {
+        await ChatService.AddReactionAsync(messageId, "👍");
+        await RefreshMessages();
+    }
+
+    private async Task HandleReactWithEmoji((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+        await RefreshMessages();
+    }
+
+    private async Task RefreshMessages()
+    {
+        if (activeChannel is null) return;
+        messages = await ChatService.GetMessagesAsync(activeChannelId, 0, messageSkip > 0 ? messageSkip : PageSize);
+    }
+
+    private async Task UpdateThreadReplyCounts()
+    {
+        threadReplyCounts.Clear();
+        foreach (var msg in messages.Where(m => m.ReplyToId is null))
+        {
